function versesForRef(ref){let a=String(ref).match(/\d+/g)||[];if(!a.length)return[];let n=a.map(Number);if(n.length===1)return[n[0]];let out=[];for(let i=n[0];i<=n[n.length-1];i++)out.push(i);return out}
