function stepChapter(d){let i=BOOKS.findIndex(b=>b.k===br.book),ch=br.chapter+d;if(ch<1){if(i<=0)return;i--;if(!bookOk(BOOKS[i]))return;br.book=BOOKS[i].k;ch=BOOKS[i].chapters}else if(ch>B().chapters){if(i>=BOOKS.length-1)return;i++;br.book=BOOKS[i].k;ch=1}br.chapter=ch;br.verse=null;buildBooks();buildChapters();render();q('#brRoot').scrollIntoView({behavior:'smooth',block:'start'})}
