function updateCommentary(){const b=B(),names=BRBN[lang()]||BRBN.ru;q('#brComTitle').textContent=T('commentaryTitle');q('#brComRef').textContent=`${names[br.book]||BRBN.ru[br.book]} ${br.chapter}${br.verse?':'+br.verse:''}`;q('#brComChapter').textContent=T('commentaryChapter');q('#brComVerse').textContent=T('commentaryVerse');q('#brComChapter').classList.toggle('on',br.comMode==='chapter');q('#brComVerse').classList.toggle('on',br.comMode==='verse');q('#brComNote').textContent=T('commentaryIntro');q('#brComHelp').textContent=T('frameHelp');q('#brComSource').textContent=T('openSource');const empty=q('#brComEmpty'),frame=q('#brComFrame');if(!b.chrys){frame.src='about:blank';empty.textContent=T('noCommentary');empty.classList.add('show');q('#brComSource').removeAttribute('href');return}empty.classList.remove('show');const u=commentaryUrl();frame.src=u;q('#brComSource').href=u}
